def transform(grid):
    # Each cell in the reduced grid reports the location of the exceptional
    # mark in a 5x3 panel: left-column marks are 5, other marks are 1.
    h,w=len(grid),len(grid[0])
    rb=[-1]+[i for i,r in enumerate(grid) if len(set(r))==1]+[h]
    cb=[-1]+[j for j in range(w) if all(r[j]==6 for r in grid)]+[w]
    out=[]
    for a,b in zip(rb,rb[1:]):
        row=[]
        for x,y in zip(cb,cb[1:]):
            pos=[(i-a-1,j-x-1) for i in range(a+1,b) for j in range(x+1,y) if grid[i][j]==5]
            if len(pos)==1:
                row.append(5 if pos[0][1]==0 else 1)
            elif len(pos)==2:
                row.append(1)
            else:
                row.append(5)
        out.append(row)
    return out
